    r"apt|unit)\b",
    re.I,
)
# Continuation fragments only (e.g. "Ste 200", "Ave N") — not "ST JOSEPH CREDIT UNION"
_STREET_CONTINUATION_RE = re.compile(
    r"^(blvd|boulevard|st|street|ave|avenue|dr|drive|rd|road|way|lane|ln|ct|court|"
    r"ste|suite)\.?"
    r"(?:\s+\d+[A-Za-z]?|\s+[A-Za-z])?$",
    re.I,
)
